/// One key, as puppeteer describes it. `location` 3 is the numpad, 4 a mobile soft key.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct KeyDefinition {
    pub key_code: Option<u32>,
    pub shift_key_code: Option<u32>,
    pub key: Option<&'static str>,
    pub shift_key: Option<&'static str>,
    pub code: Option<&'static str>,
    pub text: Option<&'static str>,
    pub shift_text: Option<&'static str>,
    pub location: Option<u32>,
}

/// Looks a key up by puppeteer's name for it (`"Enter"`, `"a"`, `"ShiftLeft"`, `"\r"`).
pub(crate) fn key_definition(name: &str) -> Option<&'static KeyDefinition> {
    KEY_DEFINITIONS.iter().find(|(n, _)| *n == name).map(|(_, d)| d)
}

